CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, virtual_cash DECIMAL(15,2) NOT NULL DEFAULT 100000.00, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE stocks (id BIGINT AUTO_INCREMENT PRIMARY KEY, symbol VARCHAR(24) NOT NULL UNIQUE, company_name VARCHAR(150) NOT NULL, sector VARCHAR(80) NOT NULL, current_price DECIMAL(15,2) NOT NULL, previous_close DECIMAL(15,2) NOT NULL, market_cap VARCHAR(50), pe_ratio DECIMAL(10,2), roe DECIMAL(10,2), dividend_yield DECIMAL(10,2), updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE holdings (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, stock_id BIGINT NOT NULL, product_type VARCHAR(20) NOT NULL DEFAULT 'DELIVERY', quantity INT NOT NULL, average_buy_price DECIMAL(15,2) NOT NULL, UNIQUE KEY uk_holding (user_id, stock_id, product_type), FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (stock_id) REFERENCES stocks(id));
CREATE TABLE trades (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, stock_id BIGINT NOT NULL, trade_type VARCHAR(8) NOT NULL, product_type VARCHAR(20) NOT NULL, quantity INT NOT NULL, price DECIMAL(15,2) NOT NULL, brokerage DECIMAL(15,2) NOT NULL, total_amount DECIMAL(15,2) NOT NULL, executed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (stock_id) REFERENCES stocks(id));
CREATE TABLE wallet_transactions (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, transaction_type VARCHAR(15) NOT NULL, method VARCHAR(30) NOT NULL, amount DECIMAL(15,2) NOT NULL, status VARCHAR(20) NOT NULL, reference_note VARCHAR(180), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE watchlist_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, stock_id BIGINT NOT NULL, UNIQUE KEY uk_watchlist (user_id, stock_id), FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (stock_id) REFERENCES stocks(id));
